import{_ as n,c as i,o as e,ae as t}from"./chunks/framework.BlRNOFgT.js";const g=JSON.parse('{"title":"Latihan Soal: Web 3.0 & Blockchain","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/web3.md","filePath":"WBD/web3.md"}'),s={name:"WBD/web3.md"};function l(r,a,o,u,k,m){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="latihan-soal-web-3-0-blockchain" tabindex="-1">Latihan Soal: Web 3.0 &amp; Blockchain <a class="header-anchor" href="#latihan-soal-web-3-0-blockchain" aria-label="Permalink to &quot;Latihan Soal: Web 3.0 &amp; Blockchain&quot;">​</a></h1><h2 id="bagian-1-konsep-evolusi-web" tabindex="-1">Bagian 1: Konsep &amp; Evolusi Web <a class="header-anchor" href="#bagian-1-konsep-evolusi-web" aria-label="Permalink to &quot;Bagian 1: Konsep &amp; Evolusi Web&quot;">​</a></h2><p><strong>1. Manakah pernyataan berikut yang secara akurat membedakan Web 3.0 dari generasi sebelumnya (Web 1.0 dan Web 2.0)?</strong></p><ul><li>A. Web 3.0 berfokus pada &quot;Read-Write-Own&quot; di mana pengguna memiliki otonomi data.</li><li>B. Infrastruktur utama Web 3.0 bergantung pada Cloud dan Mobile Devices sebagai pilar utama.</li><li>C. Identitas pengguna dikelola melalui Self-Sovereign Identity (SSI), bukan akun terpusat pada platform.</li><li>D. Web 3.0 menyelesaikan masalah User-Generated Content yang belum teratasi di Web 2.0.</li><li>E. Interaksi antar platform dimungkinkan melalui protokol Cross-chain.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah karena Cloud &amp; Mobile adalah infrastruktur Web 2.0 (Slide 16); Web 3.0 menggunakan Blockchain. Opsi D salah karena User-Generated Content adalah solusi Web 2.0, bukan masalah yang diselesaikan Web 3.0.</p></details><hr><p><strong>2. Dalam konteks ekonomi digital dan mekanisme kepercayaan di Web 3.0, manakah fakta yang valid?</strong></p><ul><li>A. Menggunakan model &quot;Fictitious Economy&quot; untuk memaksimalkan interaksi pengguna.</li><li>B. Biaya perpindahan (switching cost) antar penyedia layanan menjadi sangat rendah.</li><li>C. Kepercayaan dialihkan dari entitas platform tunggal ke protokol terdistribusi dan kode transparan.</li><li>D. Platform memiliki hak mutlak atas data pengguna untuk tujuan monetisasi iklan.</li><li>E. Menggabungkan aspek kebebasan (freedom) dan kepercayaan (trust) melalui desentralisasi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A salah, &quot;Fictitious Economy&quot; diasosiasikan dengan Web 2.0 di Slide 16, sedangkan Web 3.0 adalah Intelligent Execution/Value. Opsi D adalah karakteristik Web 2.0 yang justru ingin didisrupsi oleh Web 3.0.</p></details><hr><p><strong>3. Bagaimana mekanisme pengelolaan data dan identitas bekerja secara teknis dalam arsitektur Web 3.0?</strong></p><ul><li>A. Pengguna harus mendaftar satu kali (Single Sign-On) pada server terpusat untuk mengakses semua DApps.</li><li>B. Menggunakan infrastruktur kunci publik terdistribusi (DPKI).</li><li>C. Data pengguna dilindungi algoritma kriptografi dan disimpan di distributed ledger.</li><li>D. Akses data legal hanya dapat terjadi jika ada otorisasi tanda tangan digital (signature) pengguna.</li><li>E. Platform memegang private key pengguna untuk memulihkan akun jika hilang.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena Web 3.0 tidak mewajibkan pembuatan akun di platform (Slide 6). Opsi E fatal secara keamanan; di Web 3.0 (Self-Sovereign), pengguna memegang kendali penuh atas kunci privat mereka, bukan platform.</p></details><hr><h2 id="bagian-2-blockchain-mechanics" tabindex="-1">Bagian 2: Blockchain Mechanics <a class="header-anchor" href="#bagian-2-blockchain-mechanics" aria-label="Permalink to &quot;Bagian 2: Blockchain Mechanics&quot;">​</a></h2><p><strong>4. Jika sebuah blok (Blok B) terbentuk setelah Blok A, mekanisme apa yang menjamin integritas rantai tersebut?</strong></p><ul><li>A. Blok B menyimpan salinan penuh seluruh data dari Blok A.</li><li>B. Blok B mengandung nilai hash dari Blok A (prevHash).</li><li>C. Perubahan data pada Blok A akan mengubah hash Blok A, sehingga memutus rantai di Blok B.</li><li>D. Setiap node dalam jaringan harus menyetujui perubahan data melalui mekanisme konsensus (&gt;50%).</li><li>E. Data dalam blok dienkripsi sehingga tidak bisa dibaca oleh public node.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena blok hanya menyimpan referensi hash sebelumnya, bukan menyalin datanya. Opsi E salah konteks; ledger bersifat transparan (publik), integritas dijaga oleh hash, bukan dengan menyembunyikan data (enkripsi).</p></details><hr><p><strong>5. Komponen apa saja yang secara teknis terdapat di dalam Header dari sebuah blok (seperti pada contoh Bitcoin)?</strong></p><ul><li>A. Daftar lengkap transaksi (Transaction Data).</li><li>B. Root of Merkle Tree.</li><li>C. Hash dari blok sebelumnya.</li><li>D. Nonce.</li><li>E. Smart Contract Code.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A dan E salah karena data transaksi detail dan kode kontrak berada di Body blok. Header hanya memuat metadata ringkas (Root, PrevHash, Time, Nonce) untuk efisiensi validasi (Slide 24).</p></details><hr><p><strong>6. Terkait keamanan dan distribusi data pada Blockchain:</strong></p><ul><li>A. Modifikasi data transaksi valid hanya memerlukan persetujuan dari node yang membuat blok tersebut.</li><li>B. Jika satu node mengubah datanya sendiri, perubahan itu otomatis ditolak jika tidak sesuai dengan mayoritas node lain.</li><li>C. Seluruh chain disimpan di semua node dalam jaringan.</li><li>D. Tampering data sangat sulit karena perubahan satu karakter mengubah hash secara drastis.</li><li>E. Authorized Node memiliki hak mutlak untuk mem-veto transaksi tanpa konsensus.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena butuh konsensus mayoritas (&gt;50%), bukan hanya pembuat blok. Opsi E salah karena dalam blockchain publik/terdesentralisasi, tidak ada otoritas tunggal yang memiliki hak veto mutlak di luar mekanisme konsensus.</p></details><hr><h2 id="bagian-3-smart-contracts" tabindex="-1">Bagian 3: Smart Contracts <a class="header-anchor" href="#bagian-3-smart-contracts" aria-label="Permalink to &quot;Bagian 3: Smart Contracts&quot;">​</a></h2><p><strong>7. Apa yang membedakan Smart Contract (khususnya di Ethereum) dibandingkan skrip biasa?</strong></p><ul><li>A. Bersifat Turing-complete (contoh: Solidity).</li><li>B. Kode kontrak dapat diubah dengan mudah setelah di-deploy untuk memperbaiki bug.</li><li>C. Eksekusi program terjadi secara otomatis dan deterministik di seluruh node.</li><li>D. Memerlukan biaya eksekusi yang disebut &quot;Gas Fee&quot;.</li><li>E. Berjalan di atas server terpusat milik pengembang untuk efisiensi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B adalah pengecoh utama; salah satu tantangan terbesar Smart Contract adalah kodenya sulit/tidak bisa diubah pasca-deploy (immutability). Opsi E salah karena berjalan di atas Blockchain (terdesentralisasi).</p></details><hr><p><strong>8. Berdasarkan arsitektur dasarnya, manakah perbedaan yang benar antara Bitcoin dan Ethereum?</strong></p><ul><li>A. Bitcoin menggunakan Account Based Ledger, sedangkan Ethereum menggunakan Transaction Based.</li><li>B. Waktu blok (Out Time of Block) Ethereum jauh lebih cepat (detik) dibanding Bitcoin (menit).</li><li>C. Bitcoin menggunakan bahasa skrip sederhana, sedangkan Ethereum menggunakan bahasa kompleks (Turing-complete).</li><li>D. Ethereum menggunakan Proof of Stack (PoS) + PoW (pada konteks slide/sejarah), sedangkan Bitcoin murni PoW.</li><li>E. Total token Ethereum bersifat tetap (Fixed), sedangkan Bitcoin tidak terbatas.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A terbalik (Bitcoin itu Transaction/UTXO based, Ethereum Account based). Opsi E salah karena Bitcoin yang Fixed (21 juta), sedangkan Ethereum Unfixed (Slide 25).</p></details><hr><p><strong>9. Manakah yang merupakan keterbatasan atau tantangan nyata dari Smart Contract?</strong></p><ul><li>A. Ketergantungan pada pihak ketiga untuk memverifikasi eksekusi.</li><li>B. Tidak dapat diubah (immutable) setelah penyebaran, meningkatkan risiko jika ada celah keamanan.</li><li>C. Keterbatasan waktu/kecepatan pemrosesan dibanding aplikasi konvensional.</li><li>D. Biaya pemrosesan (gas fee) dibebankan pada saat invokasi kontrak.</li><li>E. Kode bersifat tertutup (closed source) demi alasan keamanan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena Smart Contract menghilangkan butuhnya pihak ketiga. Opsi E salah karena kode di public blockchain bersifat transparan dan dapat diverifikasi siapa saja (Slide 8/27).</p></details><hr><h2 id="bagian-4-dao-decentralized-autonomous-organizations" tabindex="-1">Bagian 4: DAO (Decentralized Autonomous Organizations) <a class="header-anchor" href="#bagian-4-dao-decentralized-autonomous-organizations" aria-label="Permalink to &quot;Bagian 4: DAO (Decentralized Autonomous Organizations)&quot;">​</a></h2><p><strong>10. Bagaimana DAO berbeda dari organisasi tradisional dalam hal manajemen dan pengambilan keputusan?</strong></p><ul><li>A. DAO memiliki struktur manajemen bertingkat (Graded Management) untuk efisiensi.</li><li>B. Keputusan dibuat melalui protokol voting yang biasanya proporsional dengan kepemilikan token.</li><li>C. Aliran dana (Money Flow) bersifat transparan dan dapat diaudit publik.</li><li>D. Memerlukan entitas hukum terpusat (Single legal entity) untuk beroperasi.</li><li>E. Aturan organisasi dijalankan oleh algoritma (Smart Contract), bukan oleh manajer manusia.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A dan D adalah ciri organisasi tradisional. DAO bersifat Distributed, Flat, dan seringkali beroperasi tanpa entitas hukum tunggal yang terpusat (Slide 29).</p></details><hr><p><strong>11. Apa peran token dalam ekosistem DAO?</strong></p><ul><li>A. Sebagai alat pembayaran gaji tetap bulanan seperti kontrak kerja konvensional.</li><li>B. Memberikan hak suara (voting rights) dalam tata kelola komunitas.</li><li>C. Berfungsi sebagai insentif untuk kontribusi anggota.</li><li>D. Sebagai bukti kepemilikan saham yang diatur oleh hukum sekuritas konvensional di semua negara.</li><li>E. Memungkinkan pembagian keuntungan (benefit sharing) secara otomatis.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena DAO tidak mengenal kontrak kerja gaji tetap konvensional, melainkan insentif berbasis kontribusi/token. Opsi D terlalu generalis dan seringkali salah karena status hukum token DAO masih abu-abu/berbeda di tiap yurisdiksi, berbeda dengan saham konvensional.</p></details><hr><h2 id="bagian-5-token-tokenomics" tabindex="-1">Bagian 5: Token &amp; Tokenomics <a class="header-anchor" href="#bagian-5-token-tokenomics" aria-label="Permalink to &quot;Bagian 5: Token &amp; Tokenomics&quot;">​</a></h2><p><strong>12. Berdasarkan fungsi dan jenisnya, manakah kategorisasi token yang tepat?</strong></p><ul><li>A. Security Token merepresentasikan investasi atau kepemilikan yang mengharapkan profit.</li><li>B. NFT digunakan untuk aset yang dapat dipertukarkan secara identik satu sama lain (fungible).</li><li>C. Token berfungsi sebagai &quot;unit atom&quot; dari Web 3.0 yang membawa kepentingan/nilai.</li><li>D. Utility Token atau Asset Type Token dapat digunakan untuk hak akses atau penggunaan platform.</li><li>E. Token diciptakan semata-mata untuk menggantikan mata uang Fiat.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B salah fatal: NFT (Non-Fungible Token) adalah untuk aset unik/koleksi, bukan fungible. Opsi E salah karena fungsi token sangat luas (hak suara, kepemilikan aset, akses), bukan hanya sebagai mata uang.</p></details><hr><p><strong>13. Mengapa sistem blockchain memberikan token rewards?</strong></p><ul><li>A. Karena biaya pemeliharaan ledger mahal (listrik/komputasi).</li><li>B. Sebagai insentif bagi node untuk melakukan tugas pembukuan (bookkeeping).</li><li>C. Untuk mencegah pengguna biasa bergabung menjadi node.</li><li>D. Untuk menciptakan inflasi buatan agar harga aset turun.</li><li>E. Sebagai mekanisme distribusi nilai dalam ekonomi kreator.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong> Opsi C salah, insentif justru menarik node baru. Opsi D salah, tujuannya adalah keamanan dan partisipasi, bukan devaluasi aset.</p></details><hr><h2 id="bagian-6-studi-kasus-aplikasi" tabindex="-1">Bagian 6: Studi Kasus &amp; Aplikasi <a class="header-anchor" href="#bagian-6-studi-kasus-aplikasi" aria-label="Permalink to &quot;Bagian 6: Studi Kasus &amp; Aplikasi&quot;">​</a></h2><p><strong>14. Seorang developer mengklaim telah membuat aplikasi Web 3.0 yang &quot;Sempurna&quot; dengan karakteristik berikut. Manakah karakteristik yang MELANGGAR prinsip dasar Web 3.0?</strong></p><ul><li>A. Aplikasi menyimpan password pengguna dalam database terenkripsi milik perusahaan.</li><li>B. Logika bisnis inti dijalankan menggunakan Smart Contract yang kodenya terbuka.</li><li>C. Admin memiliki &quot;Master Key&quot; untuk membatalkan transaksi blockchain jika ada penipuan.</li><li>D. Pengguna dapat login menggunakan dompet kripto mereka tanpa email.</li><li>E. Data aktivitas pengguna dijual ke pihak ketiga untuk menutupi biaya server.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> A melanggar prinsip Self-Sovereign Identity. C melanggar prinsip Immutability dan Decentralization (tidak boleh ada admin sentral yang bisa rollback transaksi). E melanggar prinsip Data Autonomy dan User Ownership.</p></details><hr><p><strong>15. Jika Anda ingin membangun sistem yang Censor-Resistant (tahan sensor) dan transparan, komponen apa yang wajib ada?</strong></p><ul><li>A. Penyimpanan data pada Distributed Ledger.</li><li>B. Logika aplikasi pada server AWS Lambda (Serverless).</li><li>C. Tata kelola menggunakan DAO.</li><li>D. Kode yang bersifat Open Source dan dapat diverifikasi (Smart Contract).</li><li>E. Database SQL dengan replikasi Master-Slave.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B dan E adalah teknologi Web 2.0 yang tersentralisasi. Jika server AWS/SQL dimatikan oleh penyedia (Amazon/Admin), aplikasi mati. Web 3.0 membutuhkan distribusi (Ledger) dan kode otonom.</p></details><hr><p><strong>16. Bagaimana Web 3.0 menangani batasan antar aplikasi (Ecological Boundary)?</strong></p><ul><li>A. Aplikasi bersifat terisolasi (siloed) demi keamanan data.</li><li>B. Menggunakan protokol Cross-chain untuk interkoneksi nilai.</li><li>C. Pengguna menghadapi hambatan minimal untuk masuk ke &quot;field&quot; aplikasi lain (Free Entry).</li><li>D. Perilaku pengguna tidak lagi dibatasi oleh entitas pihak ketiga.</li><li>E. Satu aplikasi &quot;Super-App&quot; menguasai semua fitur (seperti WeChat).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A dan E adalah karakteristik Web 2.0 (Walled Gardens). Web 3.0 menekankan pada Openness dan Interoperability (Slide 12-13).</p></details><hr><p><strong>17. Apa yang terjadi jika seseorang mencoba memodifikasi data transaksi di Blok #50 pada blockchain yang sudah mencapai Blok #100?</strong></p><ul><li>A. Hash blok #50 akan berubah.</li><li>B. Hash blok #51 hingga #100 akan menjadi tidak valid karena rantai prevHash putus.</li><li>C. Perubahan akan otomatis diterima jika dilakukan oleh &quot;Authorized Node&quot;.</li><li>D. Penyerang harus mengkomputasi ulang Proof-of-Work (atau konsensus) untuk blok #50 hingga #100.</li><li>E. Sistem akan menolak perubahan tersebut karena tidak sesuai dengan salinan di node lain.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi C salah. Ini adalah inti keamanan Blockchain. Mengubah data lama membutuhkan usaha komputasi ulang seluruh rantai setelahnya (D) dan akan ditolak oleh jaringan karena hash-nya berbeda (E).</p></details><hr><p><strong>18. Dalam Creator Economy Web 3.0, bagaimana hubungan antara kreator dan platform berubah?</strong></p><ul><li>A. Platform mengambil potongan mayoritas pendapatan sebagai biaya layanan.</li><li>B. Kreator memiliki kepemilikan atas konten mereka melalui token/NFT.</li><li>C. Komunitas dapat ikut serta dalam tata kelola platform (Co-construction).</li><li>D. Keuntungan dibagi secara otomatis melalui Smart Contract.</li><li>E. Hak cipta dikelola secara manual oleh tim legal platform.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A dan E adalah model Web 2.0. Web 3.0 menekankan pada distribusi nilai langsung ke kreator dan komunitas serta otomatisasi royalti.</p></details><hr><p><strong>19. Mengingat Web 3.0 belum memiliki definisi standar, manakah deskripsi yang disepakati secara umum?</strong></p><ul><li>A. Solusi masa depan untuk keamanan informasi pengguna dan kepemilikan konten.</li><li>B. &quot;A user-owned Internet&quot;.</li><li>C. Web yang hanya bisa dibaca (Read-only) namun sangat cepat.</li><li>D. Generasi ketiga teknologi Web yang menekankan otonomi pengguna.</li><li>E. Web semantik yang sepenuhnya dikendalikan oleh AI tanpa intervensi manusia.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi C adalah Web 1.0. Opsi E salah, meskipun ada aspek &quot;Intelligent Execution&quot;, Web 3.0 berpusat pada User (User-centric), bukan dominasi AI total tanpa manusia.</p></details><hr><p><strong>20. Manakah kategori Blockchain yang disebutkan dalam materi?</strong></p><ul><li>A. Public Blockchain.</li><li>B. Corporate Blockchain.</li><li>C. Consortium Blockchain.</li><li>D. Private Blockchain.</li><li>E. Government Blockchain.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Berdasarkan Slide 23, kategori yang diakui secara teknis adalah Public, Consortium, dan Private. Istilah &quot;Corporate&quot; atau &quot;Government&quot; adalah deskripsi penggunaan, bukan kategori teknis arsitektur blockchain dalam konteks slide tersebut.</p></details>',86)])])}const p=n(s,[["render",l]]);export{g as __pageData,p as default};
